    // GetStepDirectionMaybe reports the current destination unreachable).
    virtual int PickReachableDestNodeMaybe(TrackGraph *pGraph, int nFromNodeId);
    // slot 20 (+0x50) -- the "activate" entry point DecorObjMgrMaybe::
    // ActivateEligibleEntriesMaybe calls on eligible registry entries.
    virtual void ActivateMaybe();
    // slot 21 (+0x54) -- the "may I stand at this world position" test; overridden by both
    // leaves (WalkerActor::CanStandAtMaybe 0x433860, RoadVehicleActor 0x454050).
    virtual unsigned char CanStandAtMaybe(int x, int y);
