// 0xf4/244 bytes; ctor 0x4326f0, dtor 0x432740, vtable 0x477eb8 (24 slots -- adds 2 of its own
// past the base's 22). TileKind category 7: every `people\*` and `animals\*` kind.
//
// Walks the paths\* network (category 0xc). Its destinations are random category-2 building\*
// objects, picked via PickRandomBigObjByCategory. It is the only actor that can board a train.
class WalkerActor : public DecorActorBase {
public:
    // +0xec -- copied by the slot-9 copy constructor, never written anywhere else.
    //
    // It belongs to THIS class rather than to DecorActorBase, and the copy constructor is what
    // says so. Inlined whole into WalkerRegistryMaybe::SetCopyAtMaybe (0x435700,
    // src/Obj0x477798Family.cpp), it emits each base's vptr store at the END of that base's own
    // member copies -- 0x477820 after +0x20, 0x477488 after +0x86, 0x477f18 after +0xe8 and
    // 0x477eb8 after +0xf0. The 0x477f18 store landing BETWEEN the +0xe8 and +0xec copies puts
    // the boundary at 0xec, so DecorActorBase is 0xec bytes and this int opens the leaf.
    // RoadVehicleActor carries the same field for the same reason (its own 0x4780b8 store comes
    // after +0xec, which is why that class is 0xf0 and not the "no members of its own" it was
    // documented as). Declared in DecorActorBase until 2026-07-27; the two spellings are
    // layout-identical, so only the copy constructor could ever have told them apart.
    int Unk0xec;
    // +0xf0 -- the PeerTrainNode this actor has boarded, 0 when on foot. Set by
    // BoardTrainMaybe, which claims the first free slot in the train's own 8-entry passenger
    // array (PeerTrainNodePartial::apPassengerMaybe, +0x38); cleared by LeaveTrainMaybe, which
    // the dtor also calls so a deleted passenger does not leave a dangling slot behind. While
    // non-0 the actor is additionally allowed onto category-3 (track\*) tiles -- see
    // ChooseNextStepTileMaybe's tile-kind test.
    PeerTrainNode *pRidingTrainMaybe;

    WalkerActor(int kindId);
    virtual ~WalkerActor();

    // --- ordinary (non-virtual) members, all in src/WalkerActor.cpp -----------------------
    // 0x433160 -- picks the standing/idle sprite subframe from nMoodMaybe: 5 when the mood is
    // 0, 6 below 3, 4 below 5, else 7. Only ever changes it when it differs.
    void UpdateIdlePoseFromMoodMaybe();
    // 0x4331b0 -- picks the WALKING sprite subframe from the dominant axis of
    // nStepDelta{X,Y}: on a mostly-horizontal step 0 for left / 2 for right, otherwise 3 for
    // up / 1 for down.
    void UpdateFacingFromStepDeltaMaybe();
    // 0x433370 -- the track-tile gate: what to do about the track\* tile at (x, y).
    unsigned char TryEnterTrackTileMaybe(int x, int y);
    // 0x433530 -- board pTrain (0 == get off whatever we are on).
    unsigned char BoardTrainMaybe(PeerTrainNodePartial *pTrain);
    // 0x4336a0 -- step off the train: clear this actor out of pRidingTrainMaybe's own
    // passenger array, null the field, and place it back down beside the track.
    void LeaveTrainMaybe();

    virtual void TickMaybe(DecorActorBase *pNextActor); // slot 15 -- 0x4327b0
    virtual void SetDestinationTileMaybe(int x, int y); // slot 16 -- 0x432940
    virtual void ChooseNextStepTileMaybe(int x, int y); // slot 18 -- 0x432ae0
    virtual unsigned char CanStandAtMaybe(int x, int y); // slot 21 -- 0x433860
    // slots 22/23 -- this class's own two NEW slots, past the base's 22. Both are steppers
    // its own TickMaybe dispatches virtually rather than calling directly, and neither is
    // overridden anywhere, so the indirection is only ever self-dispatch.
    // 0x432fd0 -- one movement sub-step: aboard a train, ride along with it (and get off on
    // arrival); on foot, advance toward nStepPos at the kind's own speed. Returns the
    // remaining nStepDistanceMaybe, which its caller tests for 0 ("arrived").
    virtual int AdvanceMovementMaybe();
    // 0x433220 -- the population-throttle stepper: step toward pLeader's published trail
    // anchor instead of doing any path work of our own. Also returns nStepDistanceMaybe.
    virtual int FollowLeaderStepMaybe(DecorActorBase *pLeader);
};

// 0xf0/240 bytes; ctor 0x4533d0, dtor 0x4533f0, vtable 0x4780b8 (29 slots -- adds 7 of its own).
// TileKind category 8: every `vehicles\*` kind (van, ferrari, milkflot, ferr2, engine).
// Adds no data members at all past DecorActorBase.
//
// Drives the roads\* network (category 0xd); its destination is a placed instance of a randomly
// chosen road kind id (`0x3400 + rand() % 0x29` -- exactly the 41 road kinds in
// docs/TILEKIND_IDS.md's category 0xd), and it is placed on its owner's tile at spawn with no
// randomisation and no activate call, unlike WalkerActor.
class RoadVehicleActor : public DecorActorBase {
public:
    // +0xec -- this class's ONLY data member, and the twin of WalkerActor::Unk0xec above (see
    // that note for how the copy constructor pins it to the leaf rather than to the base).
    int Unk0xec;

    RoadVehicleActor(int kindId);
    virtual ~RoadVehicleActor();

    // --- ordinary (non-virtual) member, in src/RoadVehicleActor.cpp ------------------------
    // 0x453fb0 -- picks the driving sprite subframe from the SIGNS of nStepDelta{X,Y}: unlike
    // WalkerActor's 4-way dominant-axis test this is a full 8-way compass, and the eight even
    // subframes 0..14 are laid out W, SW, S, SE, E, NE, N, NW.
    void UpdateFacingFromStepDeltaMaybe();

    virtual void TickMaybe(DecorActorBase *pNextActor); // slot 15 -- 0x453450
    virtual void SetDestinationTileMaybe(int x, int y); // slot 16 -- 0x453570
    virtual void ChooseNextStepTileMaybe(int x, int y); // slot 18 -- 0x453790 (1499 bytes, the
                                        //   single largest unclaimed app-region function)
    virtual unsigned char CanStandAtMaybe(int x, int y); // slot 21 -- 0x454050
    // slots 22/23 -- this class's own two NEW slots past the base's 22, exactly like
    // WalkerActor's own pair (the two leaves' slot numbers coincide but the slots are
    // independent -- neither class overrides the other's).
    // 0x453eb0 -- one movement sub-step. Moves first and asks questions after: it repositions
    // to the new step target, queries the manager for a pixel-accurate collision against every
    // other actor, and only keeps the move if that came back clear AND CanStandAtMaybe agrees.
    // Otherwise it puts itself back and, unless the collision code was 7, drops its target.
    virtual int AdvanceMovementMaybe();
    // 0x453d70 -- the road-lane offset table: nudge *pPos off the tile centre by a few pixels
    // according to the direction being driven IN and the direction being turned OUT to, so a
    // vehicle sits on the correct side of the road and cuts corners plausibly. Directions are
    // the same 0-3 the tile graph uses (0 = -x, 1 = +y, 2 = +x, 3 = -y, reverse == (d+2)&3);
    // 0xff means "no direction" and leaves the point alone, as does a (-1,-1) point. The
    // offsets encode LEFT-HAND traffic -- see the table in src/RoadVehicleActor.cpp.
    virtual void ApplyLaneOffsetMaybe(POINT *pPos, unsigned char nDirIn, unsigned char nDirOut);
};
